// Real Chromium acceptance: production DOM/import, persistent profile and the
// existing explicit PWA update. The next release is synthetic and local only;
// both worker packages are generated by the supported production builder.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const http = require('node:http');
const { execFileSync } = require('node:child_process');
const { chromium } = require('playwright');
const repo = path.resolve(__dirname, '../../..');
const fixture = '[Event "Disposable Chromium full-game resume R1"]\n[White "Fixture A"]\n[Black "Fixture B"]\n[Result "*"]\n\n1. e4 {Preserve the imported comment} e5 2. Nf3 *';
const key = 'ChessBest:LAB:v2:game';
const mime = { '.html': 'text/html', '.js': 'application/javascript', '.json': 'application/json',
  '.css': 'text/css', '.png': 'image/png', '.wasm': 'application/wasm', '.webmanifest': 'application/manifest+json' };

test('Chromium file import, four cursors, explicit worker update, close/reopen and APP share the complete line',
  { timeout: 120000 }, async t => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'chess-resume-'));
  const evidence = process.env.CHESS_RESUME_EVIDENCE_DIR || path.join(tmp, 'evidence');
  fs.mkdirSync(evidence, { recursive: true });
  const staged = path.join(tmp, 'next-release');
  fs.mkdirSync(path.join(staged, 'tools'), { recursive: true });
  fs.cpSync(path.join(repo, 'tools/chess-pwa'), path.join(staged, 'tools/chess-pwa'), { recursive: true });
  fs.copyFileSync(path.join(repo, 'tools/build-chess-channel-pwas.py'), path.join(staged, 'tools/build-chess-channel-pwas.py'));
  for (const channel of ['chess', 'chess-lab']) {
    const base = path.join(repo, 'public', channel);
    const release = JSON.parse(fs.readFileSync(path.join(base, 'release.json')));
    for (const asset of Object.keys(release.assets_sha256)) {
      const dest = path.join(staged, 'public', channel, asset);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.copyFileSync(path.join(base, asset), dest);
    }
  }
  const nextHTML = path.join(staged, 'public/chess-lab/index.html');
  fs.writeFileSync(nextHTML, fs.readFileSync(nextHTML, 'utf8').replace('</head>',
    '<!-- Local acceptance: synthetic following release. -->\n</head>'));
  execFileSync('python3', [path.join(staged, 'tools/build-chess-channel-pwas.py')]);
  const originalRelease = JSON.parse(fs.readFileSync(path.join(repo, 'public/chess-lab/release.json'))).version;
  const nextRelease = JSON.parse(fs.readFileSync(path.join(staged, 'public/chess-lab/release.json'))).version;
  assert.notEqual(originalRelease, nextRelease);
  const pgnPath = path.join(tmp, 'disposable-full-game.pgn'); fs.writeFileSync(pgnPath, fixture);
  let next = false;
  const server = http.createServer((request, response) => {
    const pathname = decodeURIComponent(new URL(request.url, 'http://fixture').pathname);
    const rel = pathname.endsWith('/') ? pathname + 'index.html' : pathname;
    if (rel.includes('..')) { response.writeHead(400).end(); return; }
    const candidate = path.join(staged, 'public', rel);
    const filename = next && ['/chess-lab/index.html', '/chess-lab/sw.js', '/chess-lab/release.json'].includes(rel)
      ? candidate : path.join(repo, 'public', rel);
    if (!fs.existsSync(filename) || !fs.statSync(filename).isFile()) { response.writeHead(404).end(); return; }
    response.writeHead(200, { 'Content-Type': mime[path.extname(filename)] || 'text/plain', 'Cache-Control': 'no-store' });
    fs.createReadStream(filename).pipe(response);
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const origin = `http://127.0.0.1:${server.address().port}`;
  let context, completed = false;
  const errors = [], results = [];
  t.after(async () => {
    if (!completed) {
      fs.writeFileSync(path.join(evidence, 'browser-failure.json'), JSON.stringify({ results, errors }, null, 2));
      await context?.pages()[0]?.screenshot({ path: path.join(evidence, 'failure.png'), timeout: 5000 }).catch(() => {});
    }
    await context?.close(); await new Promise(resolve => server.close(resolve)); fs.rmSync(tmp, { recursive: true, force: true });
  });
  const profile = path.join(tmp, 'profile');
  const open = async () => {
    context = await chromium.launchPersistentContext(profile, { headless: true, viewport: { width: 1440, height: 1000 } });
    context.setDefaultTimeout(10000);
    await context.route('**/*', route => new URL(route.request().url()).origin === origin ? route.continue() : route.abort());
    const page = context.pages()[0] || await context.newPage();
    page.on('pageerror', error => errors.push(error.message));
    await page.goto(origin + '/chess-lab/');
    await page.waitForFunction(() => !!window.ChessLabHost);
    return page;
  };
  let page = await open();
  const snapshot = () => page.evaluate(k => {
    const h = window.ChessLabHost, r = h.getReviewGame(), c = h.getContext();
    return { sans: r.moves.map(m => m.san), cursor: r.cursor, totalPly: r.totalPly, fen: c.fen,
      headers: r.headers, sourcePGN: r.sourcePGN, record: JSON.parse(localStorage.getItem(k)) };
  }, key);
  const check = (actual, expected, label) => {
    assert.deepEqual(actual, expected, label); results.push({ label, ...actual });
  };
  await page.locator('#btnWorkspaceMore').click();
  const chooser = page.waitForEvent('filechooser'); await page.locator('#btnLoad').click();
  await (await chooser).setFiles(pgnPath);
  await page.waitForFunction(() => window.ChessLabHost?.getReviewGame().totalPly === 3);
  await page.waitForFunction(() => navigator.serviceWorker.controller?.scriptURL.endsWith('/engine-sw.js'));
  const imported = await snapshot();
  assert.deepEqual(imported.sans, ['e4', 'e5', 'Nf3']); assert.equal(imported.sourcePGN, fixture);
  for (const cursor of [0, 1, 2, 3]) {
    await page.locator('#first').click();
    for (let n = 0; n < cursor; n++) await page.locator('#next').click();
    const expected = await snapshot(); assert.equal(expected.totalPly, 3); assert.equal(expected.cursor, cursor);
    await page.reload(); await page.waitForFunction(() => !!window.ChessLabHost);
    check(await snapshot(), expected, `ordinary reload cursor ${cursor}`);
  }
  await page.locator('#first').click(); await page.locator('#next').click();
  const beforeUpdate = await snapshot(); assert.equal(beforeUpdate.cursor, 1);
  next = true;
  await page.evaluate(async () => (await navigator.serviceWorker.getRegistration()).update());
  await page.locator('#chessPwaUpdate').waitFor({ state: 'visible' });
  await Promise.all([page.waitForNavigation({ waitUntil: 'load' }), page.locator('#chessPwaUpdate').click()]);
  await page.waitForFunction(() => !!window.ChessLabHost);
  check(await snapshot(), beforeUpdate, 'actual explicit PWA update at ordinary cursor 1');
  assert(await page.evaluate(() => document.documentElement.outerHTML.includes('Local acceptance: synthetic following release.')));
  assert(await page.evaluate(async release => (await caches.keys()).some(k => k.endsWith(release)), nextRelease));
  await page.screenshot({ path: path.join(evidence, 'ordinary-after-explicit-update.png'), fullPage: true });
  await context.close(); context = null;
  page = await open();
  check(await snapshot(), beforeUpdate, 'persistent browser profile close/reopen');
  await page.goto(origin + '/chess-lab/?view=app');
  await page.waitForFunction(() => !!window.ChessLabHost && document.body.classList.contains('app-mobile'));
  check(await snapshot(), beforeUpdate, 'APP uses same complete game/cursor namespace');
  await page.locator('[data-app-tab="board"]').click();
  await page.locator('#last').click(); assert.equal((await snapshot()).cursor, 3);
  await page.locator('#first').click(); await page.locator('#next').click();
  await page.reload(); await page.waitForFunction(() => !!window.ChessLabHost);
  check(await snapshot(), beforeUpdate, 'APP ordinary reload at cursor 1');
  await page.locator('#appMore').click(); await page.locator('#btnSettings').click();
  assert.equal(await page.locator('#desktopNavRow').isVisible(), false);
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('#desktopNavRow').isVisible(), true);
  await page.locator('#appGames').click(); await page.locator('[data-app-tab="deep"]').click();
  assert.equal(await page.locator('#popularGamesPanel').isVisible(), false);
  assert.equal(await page.locator('#deepAnalysisPanel').isVisible(), true);
  await page.screenshot({ path: path.join(evidence, 'app-retention-gui-smoke.png'), fullPage: true });
  assert.deepEqual(errors, []);
  fs.writeFileSync(path.join(evidence, 'browser-acceptance.json'), JSON.stringify({
    schema: 'chessbest-full-game-browser-qa/1', originalRelease, nextRelease,
    fixtureOnly: true, physicalDevice: false, results, errors }, null, 2) + '\n');
  completed = true;
});
